import 'package:ble_peripheral_plus/ble_peripheral_plus.dart';

Future<void> startPeripheral() async {
  await BlePeripheral.initialize();
  if (!await BlePeripheral.isSupported()) throw Exception('Not supported');
  await BlePeripheral.clearServices();
  await BlePeripheral.addService(
    BleService(
      uuid: '0000180F-0000-1000-8000-00805F9B34FB',
      primary: true,
      characteristics: [
        BleCharacteristic(
          uuid: '00002A19-0000-1000-8000-00805F9B34FB',
          properties: [CharacteristicProperties.read.index, CharacteristicProperties.notify.index],
          permissions: [AttributePermissions.readable.index],
          value: Uint8List.fromList([100]),
        ),
      ],
    ),
  );
  await BlePeripheral.startAdvertising(
    services: ['0000180F-0000-1000-8000-00805F9B34FB'],
    localName: 'Battery',
    requireBonding: true,
  );
}
